// 분류 객체: { code, name, keywords, group, isGroup }
function groupOf_(code) {
  code = String(code);
  return code.length >= 4 ? code.slice(0, code.length - 2) + '00' : code[0] + '00';
}

function defaultCategories_() {
  return DEFAULT_CAT_RAW.split('\n').map(function (line) {
    var p = line.split('|');
    return { code: p[0], name: p[1], keywords: p[2] ? p[2].split(',').map(function (s) { return s.trim().toLowerCase(); }).filter(String) : [] };
  });
}

var _cats = null;
function categories_() {
  if (_cats) return _cats;
  var list = rows_('categories').filter(function (c) { return /^\d{3,4}$/.test(c.code); });
  list.forEach(function (c) { c.group = groupOf_(c.code); c.isGroup = c.code.slice(-2) === '00'; });
  list.sort(function (a, b) { return Number(a.code) - Number(b.code); });
  _cats = list;
  return list;
}
function catName_(code) { var c = categories_().filter(function (x) { return x.code === String(code); })[0]; return c ? c.name : ''; }
function groupName_(code) { return catName_(groupOf_(code)); }
function leafCategories_() {
  var cats = categories_();
  return cats.filter(function (c) { return !c.isGroup || !cats.some(function (x) { return x.group === c.code && !x.isGroup; }); });
}

// KDC(한국십진분류) / ISBN 부가기호 → 오스템 분류
function mapKDC_(kdcRaw) {
  if (!kdcRaw) return null;
  var s = String(kdcRaw).replace(/[^0-9.]/g, '');
  if (!s) return null;
  var k = Math.floor(parseFloat(s));
  function r(leaf, group) { return { leaf: leaf, group: group || (leaf ? groupOf_(leaf) : null) }; }
  if (k < 100) return (k === 4 || k === 5) ? r('1109') : r('401');
  if (k < 200) { if (k >= 180 && k < 190) return r('404'); if (k >= 140 && k < 160) return r('409'); if (k >= 160 && k < 180) return r('403'); return r('402'); }
  if (k < 300) return r(null, '900');
  if (k < 400) {
    if (k === 325) return r('130'); if (k === 327) return r('137'); if (k === 326) return r('123');
    if (k >= 320 && k < 330) return r('125'); if (k >= 330 && k < 340) return r('1005'); if (k === 349) return r('1003');
    if (k >= 340 && k < 350) return r('1006'); if (k >= 360 && k < 370) return r('1007'); if (k >= 370 && k < 380) return r('1500');
    if (k >= 380 && k < 390) return r('407'); return r(null, '1000');
  }
  if (k < 500) { if (k >= 410 && k < 420) return r('803'); if (k >= 440 && k < 450) return r('805'); if (k >= 470) return r('804'); return r('802'); }
  if (k < 600) { if (k === 516 || k === 517) return r('1302'); if (k >= 510 && k < 520) return r('1201'); if (k >= 590) return r('1500'); if (k >= 560 && k < 570) return r('1112'); return r(null, '1300'); }
  if (k < 700) return r('407');
  if (k < 800) { if (k >= 720 && k < 730) return r('502'); if (k >= 730 && k < 740) return r('503'); if (k >= 740 && k < 750) return r('501'); return r('223'); }
  if (k < 900) {
    var lang = Math.floor(k / 10) % 10, form = k % 10;
    if (k === 802) return r('223');
    if (form === 1) return r(lang === 1 ? '703' : null, '700');
    if (form === 3) { if (lang === 1) return r('602'); if (lang === 3) return r('607'); if (lang === 4) return r('604'); if (lang === 5) return r('606'); return r(null, '600'); }
    if (form === 4 || form === 6 || form === 8) { if (lang === 1) return r('701'); if (lang === 3) return r('704'); if (lang === 4) return r('702'); return r(null, '700'); }
    return r(null, '600');
  }
  if (k === 911) return r('307'); if (k === 913) return r('308'); if (k >= 920 && k < 930) return r('302'); if (k === 909) return r('305');
  return r('309');
}
function kdcFromAddCode_(addCode) { var s = String(addCode || '').replace(/\D/g, ''); return s.length === 5 ? s.slice(2) : null; }

// ===== Classifier.gs =====
// 자동 분류 + 도서코드 생성
// 1) 같은 책(ISBN/제목)이 있으면 같은 소분류·구매번호, 권번호 +1
// 2) 없으면 점수 합산: 기존 장서 제목 유사도 + 같은 저자 + KDC/부가기호 + 분류 키워드
function normStr_(s) { return String(s || '').toLowerCase().replace(/\(.*?\)|\[.*?\]/g, '').replace(/[^0-9a-z가-힣]/g, ''); }
function normTitle_(s) { return normStr_(String(s || '').split(/[:：\-–]/)[0]); }
function bigrams_(s) { var t = normStr_(s), set = {}; for (var i = 0; i < t.length - 1; i++) set[t.slice(i, i + 2)] = 1; if (t.length === 1) set[t] = 1; return set; }
function sim_(a, b) {
  var ka = Object.keys(a), kb = Object.keys(b);
  if (!ka.length || !kb.length) return 0;
  var inter = 0; ka.forEach(function (x) { if (b[x]) inter++; });
  return inter / Math.sqrt(ka.length * kb.length);
}
function authorKey_(a) { return normStr_(String(a || '').split(/[,/·]| 외| 지음| 저/)[0]); }

function findSameBook_(books, input) {
  var i = String(input.isbn || '').replace(/\D/g, ''), t = normTitle_(input.title);
  return books.filter(function (b) { return b.status !== 'discarded' && ((i && b.isbn === i) || (t && normTitle_(b.title) === t)); });
}

function classify_(input) {
  var leafs = leafCategories_();
  var leafSet = {}; leafs.forEach(function (c) { leafSet[c.code] = c; });
  var books = rows_('books').filter(function (b) { return b.status !== 'discarded'; });
  var scores = {}, reasons = {};
  function add(code, pts, why) { if (!leafSet[code]) return; scores[code] = (scores[code] || 0) + pts; (reasons[code] = reasons[code] || []).push(why); }

  var same = findSameBook_(books, input);
  if (same.length) add(same[0].catCode, 1000, '이미 보유 중인 도서 (' + same[0].code + ') — 같은 분류로 추가 권 등록');

  var q = bigrams_(input.title);
  books.map(function (b) { return { b: b, s: sim_(q, bigrams_(b.title)) }; })
    .filter(function (x) { return x.s > 0.25; }).sort(function (x, y) { return y.s - x.s; }).slice(0, 7)
    .forEach(function (x) { add(x.b.catCode, Math.round(x.s * 30), '제목 유사: 「' + x.b.title + '」'); });

  var ak = authorKey_(input.author);
  if (ak && ak.length >= 2) {
    var seen = {};
    books.filter(function (b) { return authorKey_(b.author) === ak; }).forEach(function (b) {
      if (seen[b.catCode]) return; seen[b.catCode] = 1;
      add(b.catCode, 25, '같은 저자의 보유 도서: 「' + b.title + '」');
    });
  }

  var k = mapKDC_(input.kdc);
  if (k) {
    if (k.leaf) add(k.leaf, 30, '국립중앙도서관 분류(KDC ' + input.kdc + ')');
    if (k.group) leafs.forEach(function (c) { if (c.group === k.group && c.code !== k.leaf) add(c.code, 8, 'KDC 대분류 일치'); });
  }

  var title = String(input.title || '').toLowerCase().replace(/\s/g, '');
  var desc = String(input.description || '').toLowerCase().replace(/\s/g, '').slice(0, 1500);
  leafs.forEach(function (c) {
    (c.keywords || []).forEach(function (kw) {
      var kwn = kw.replace(/\s/g, '');
      if (kwn.length < 2 && !/[a-z]/.test(kwn)) return;
      if (title.indexOf(kwn) >= 0) add(c.code, 12, "제목 키워드 '" + kw + "'");
      else if (desc.indexOf(kwn) >= 0) add(c.code, 3, "소개글 키워드 '" + kw + "'");
    });
  });
  var cats = (input.categories || []).join(' ').toLowerCase();
  [[/business|economics|management/, '130'], [/self-help/, '205'], [/psychology/, '404'], [/philosophy/, '402'], [/history/, '309'], [/science/, '802'], [/computers/, '1109'], [/fiction/, '604'], [/medical/, '1201'], [/family|parenting/, '1500']]
    .forEach(function (p) { if (p[0].test(cats)) add(p[1], 10, "Google Books 분류 '" + input.categories.join(', ') + "'"); });

  var ranked = Object.keys(scores).map(function (code) { return [code, scores[code]]; }).sort(function (a, b) { return b[1] - a[1]; }).slice(0, 5)
    .map(function (p) {
      var uniq = []; reasons[p[0]].forEach(function (r) { if (uniq.indexOf(r) < 0) uniq.push(r); });
      return { code: p[0], name: leafSet[p[0]].name, groupName: groupName_(p[0]), score: p[1], reasons: uniq.slice(0, 3) };
    });
  var top = ranked.length ? ranked[0].score : 1;
  ranked.forEach(function (r) { r.confidence = Math.round(r.score / top * 100); });
  if (input.forceCat && !ranked.some(function (r) { return r.code === String(input.forceCat); }) && leafSet[input.forceCat]) {
    ranked.push({ code: String(input.forceCat), name: leafSet[input.forceCat].name, groupName: groupName_(input.forceCat), score: 0, confidence: 0, reasons: ['직접 선택'] });
  }
  ranked.forEach(function (r) { r.preview = nextCode_(r.code, input, Number(input.count) || 1); });
  return { candidates: ranked, sameBooks: same.map(function (b) { return { code: b.code, title: b.title }; }) };
}

// 코드: 소분류-구매번호(3자리)-권번호
function nextCode_(catCode, input, count) {
  var inCat = rows_('books').filter(function (b) { return b.catCode === String(catCode); });
  var same = findSameBook_(inCat, input);
  var purchaseNo, start;
  if (same.length) {
    purchaseNo = same[0].purchaseNo;
    start = inCat.filter(function (b) { return b.purchaseNo === purchaseNo; }).reduce(function (m, b) { return Math.max(m, Number(b.copyNo) || 0); }, 0) + 1;
  } else {
    purchaseNo = ('00' + (inCat.reduce(function (m, b) { return Math.max(m, Number(b.purchaseNo) || 0); }, 0) + 1)).slice(-3);
    start = 1;
  }
  var codes = [];
  for (var i = 0; i < (count || 1); i++) codes.push({ catCode: String(catCode), purchaseNo: purchaseNo, copyNo: String(start + i), code: catCode + '-' + purchaseNo + '-' + (start + i) });
  return { codes: codes, isAdditionalCopy: !!same.length };
}

// ===== Lookup.gs =====
// 도서정보 조회 + 실제 표지 이미지
// 키 없이: Google Books + 교보문고 표지(ISBN) / 키가 있으면: 카카오·국립중앙도서관·네이버 추가 (관리 › 설정에서 입력)
function apiKeys_() {
  var p = props_();
  return { kakao: p.getProperty('KAKAO_REST_KEY') || '', nl: p.getProperty('NL_CERT_KEY') || '', naverId: p.getProperty('NAVER_CLIENT_ID') || '', naverSecret: p.getProperty('NAVER_CLIENT_SECRET') || '' };
}
function providers_() { var k = apiKeys_(); return { kakao: !!k.kakao, nl: !!k.nl, naver: !!(k.naverId && k.naverSecret), google: true }; }

function stripTags_(s) { return String(s || '').replace(/<[^>]+>/g, '').replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim(); }
function isbn13_(s) { var parts = String(s || '').split(/\s+/).map(function (x) { return x.replace(/[^0-9Xx]/g, ''); }); return parts.filter(function (p) { return p.length === 13; })[0] || parts.filter(function (p) { return p.length === 10; })[0] || ''; }

// 여러 요청을 병렬로 보내고 JSON 파싱
function fetchJsonAll_(reqs) {
  if (!reqs.length) return [];
  var res;
  try { res = UrlFetchApp.fetchAll(reqs.map(function (r) { return { url: r.url, headers: r.headers || {}, muteHttpExceptions: true }; })); } catch (e) { return reqs.map(function () { return null; }); }
  return res.map(function (x) { try { return x.getResponseCode() === 200 ? JSON.parse(x.getContentText()) : null; } catch (e) { return null; } });
}

function parseKakao_(j) { return ((j && j.documents) || []).map(function (d) { return { source: 'kakao', title: d.title, author: (d.authors || []).join(', '), publisher: d.publisher, isbn: isbn13_(d.isbn), pubDate: String(d.datetime || '').slice(0, 10), cover: d.thumbnail, description: stripTags_(d.contents) }; }); }
function parseNl_(j) { return ((j && j.docs) || []).map(function (d) { return { source: 'nl', title: d.TITLE, author: d.AUTHOR, publisher: d.PUBLISHER, isbn: d.EA_ISBN, pubDate: String(d.PUBLISH_PREDATE || '').replace(/(\d{4})(\d{2})(\d{2})/, '$1-$2-$3'), cover: d.TITLE_URL, description: '', kdc: d.KDC || kdcFromAddCode_(d.EA_ADD_CODE) }; }); }
function parseNaver_(j) { return ((j && j.items) || []).map(function (d) { return { source: 'naver', title: stripTags_(d.title), author: stripTags_(d.author).replace(/\^/g, ', '), publisher: stripTags_(d.publisher), isbn: isbn13_(d.isbn), pubDate: String(d.pubdate || '').replace(/(\d{4})(\d{2})(\d{2})/, '$1-$2-$3'), cover: d.image, description: stripTags_(d.description) }; }); }
function parseGoogle_(j) {
  return ((j && j.items) || []).map(function (it) {
    var v = it.volumeInfo || {};
    var id13 = (v.industryIdentifiers || []).filter(function (x) { return x.type === 'ISBN_13'; })[0];
    return { source: 'google', title: [v.title, v.subtitle].filter(Boolean).join(': '), author: (v.authors || []).join(', '), publisher: v.publisher || '', isbn: id13 ? id13.identifier : '', pubDate: v.publishedDate || '', cover: String((v.imageLinks || {}).thumbnail || '').replace('http://', 'https://'), description: v.description || '', categories: v.categories || [] };
  });
}

function bookRequests_(input) {
  var k = apiKeys_();
  var isbn = String(input.isbn || '').replace(/\D/g, '');
  var q = isbn.length >= 10 ? isbn : [input.title, input.author].filter(Boolean).join(' ');
  var reqs = [];
  if (k.kakao) reqs.push({ p: parseKakao_, url: 'https://dapi.kakao.com/v3/search/book?size=10&target=' + (isbn.length >= 10 ? 'isbn' : 'title') + '&query=' + encodeURIComponent(isbn.length >= 10 ? isbn : input.title), headers: { Authorization: 'KakaoAK ' + k.kakao } });
  if (k.nl) reqs.push({ p: parseNl_, url: 'https://www.nl.go.kr/seoji/SearchApi.do?cert_key=' + encodeURIComponent(k.nl) + '&result_style=json&page_no=1&page_size=10&' + (isbn.length >= 10 ? 'isbn=' + isbn : 'title=' + encodeURIComponent(input.title)) });
  if (k.naverId && k.naverSecret) reqs.push({ p: parseNaver_, url: 'https://openapi.naver.com/v1/search/book.json?display=10&query=' + encodeURIComponent(q), headers: { 'X-Naver-Client-Id': k.naverId, 'X-Naver-Client-Secret': k.naverSecret } });
  reqs.push({ p: parseGoogle_, url: 'https://www.googleapis.com/books/v1/volumes?maxResults=10&q=' + encodeURIComponent(isbn.length >= 10 ? 'isbn:' + isbn : 'intitle:' + input.title + (input.author ? ' inauthor:' + String(input.author).split(',')[0] : '')) });
  return reqs;
}

function searchBooks_(input) {
  var reqs = bookRequests_(input);
  var out = fetchJsonAll_(reqs);
  var all = [];
  out.forEach(function (j, i) { all = all.concat(reqs[i].p(j)); });
  // ISBN 기준으로 합치기 (빈 필드는 다른 출처로 채움)
  var map = {}, order = [];
  all.forEach(function (r) {
    var key = r.isbn || r.title;
    if (!map[key]) { map[key] = r; order.push(key); }
    else Object.keys(r).forEach(function (f) { if (!map[key][f] && r[f]) map[key][f] = r[f]; });
  });
  var n = function (s) { return String(s || '').replace(/\s/g, '').toLowerCase(); };
  var score = function (r) { return (input.author && n(r.author).indexOf(n(input.author).slice(0, 3)) >= 0 ? 2 : 0) + (input.publisher && n(r.publisher).indexOf(n(input.publisher)) >= 0 ? 2 : 0) + (n(r.title) === n(input.title) ? 3 : 0) + (r.source === 'kakao' ? 1 : 0); };
  var list = order.map(function (k) { return map[k]; });
  list.forEach(function (r) { if (r.isbn && (!r.cover || r.source === 'google')) r.coverCandidate = kyoboCover_(r.isbn); });
  return list.sort(function (a, b) { return score(b) - score(a); });
}

function kyoboCover_(isbn) { return 'https://contents.kyobobook.co.kr/sih/fit-in/458x0/pdt/' + isbn + '.jpg'; }
function links_(isbn, title) {
  return { kyobo: 'https://search.kyobobook.co.kr/search?keyword=' + encodeURIComponent(isbn || title), nl: 'https://www.nl.go.kr/NL/contents/search.do?srchTarget=total&kwd=' + encodeURIComponent(isbn || title) };
}

// 이미지 URL이 실제 이미지인지 확인 (교보 → 카카오/구글 순)
function isImage_(resp) {
  if (!resp || resp.getResponseCode() !== 200) return false;
  var h = resp.getHeaders(); var ct = String(h['Content-Type'] || h['content-type'] || '');
  return /^image\//.test(ct) && resp.getBlob().getBytes().length > 2000;
}

// 표지가 비어 있는 도서를 묶음으로 확인해 표지URL 저장 (매일 자동 + 관리자 버튼)
function fillCovers_(limit) {
  var books = rows_('books').filter(function (b) { return b.isbn && !b.cover && !b.coverCheckedAt && b.status !== 'discarded'; });
  var byIsbn = {}; books.forEach(function (b) { (byIsbn[b.isbn] = byIsbn[b.isbn] || []).push(b); });
  var isbns = Object.keys(byIsbn).slice(0, limit || 120);
  if (!isbns.length) return { checked: 0, found: 0, remaining: 0 };
  var resp;
  try { resp = UrlFetchApp.fetchAll(isbns.map(function (i) { return { url: kyoboCover_(i), muteHttpExceptions: true, followRedirects: true }; })); } catch (e) { resp = []; }
  var found = 0, missing = [];
  isbns.forEach(function (isbn, i) {
    if (isImage_(resp[i])) { byIsbn[isbn].forEach(function (b) { b.cover = kyoboCover_(isbn); }); found++; }
    else missing.push(isbn);
  });
  // 교보에 없으면 카카오(키 있을 때) → Google Books 표지
  if (missing.length) {
    var k = apiKeys_();
    var reqs = missing.map(function (isbn) {
      return k.kakao ? { url: 'https://dapi.kakao.com/v3/search/book?target=isbn&query=' + isbn, headers: { Authorization: 'KakaoAK ' + k.kakao }, p: parseKakao_ }
        : { url: 'https://www.googleapis.com/books/v1/volumes?q=isbn:' + isbn, p: parseGoogle_ };
    });
    var js = fetchJsonAll_(reqs);
    missing.forEach(function (isbn, i) {
      var r = reqs[i].p(js[i])[0];
      if (r && r.cover) { byIsbn[isbn].forEach(function (b) { b.cover = r.cover; if (!b.description && r.description) b.description = String(r.description).slice(0, 3000); }); found++; }
    });
  }
  var stamp = today_();
  var changed = [];
  isbns.forEach(function (isbn) { byIsbn[isbn].forEach(function (b) { b.coverCheckedAt = stamp; changed.push(b); }); });
  save_('books', changed);
  var remaining = Object.keys(byIsbn).length - isbns.length;
  return { checked: isbns.length, found: found, remaining: remaining };
}

// 상세 화면에서 소개글이 없으면 1회 조회해 저장
function enrichOnce_(books) {
  var first = books[0];
  if (!first.isbn || first.description || books.some(function (b) { return /^info:/.test(b.kdc); })) return;
  var reqs = bookRequests_({ isbn: first.isbn });
  var js = fetchJsonAll_(reqs);
  var all = []; js.forEach(function (j, i) { all = all.concat(reqs[i].p(j)); });
  var info = {}; all.forEach(function (r) { ['cover', 'description', 'pubDate', 'kdc'].forEach(function (f) { if (!info[f] && r[f]) info[f] = r[f]; }); });
  books.forEach(function (b) {
    if (!b.cover && info.cover) b.cover = info.cover;
    if (!b.description && info.description) b.description = String(info.description).slice(0, 3000);
    if (!b.pubDate && info.pubDate) b.pubDate = info.pubDate;
    b.kdc = 'info:' + (info.kdc || b.kdc || '');
  });
  save_('books', books);
}

// ===== Service.gs =====
// 업무 로직: 도서·대출·반납·연장·예약 (사번 기반)
var OPEN = ['active', 'returning'];
function titleKey_(b) { return b.catCode + '-' + b.purchaseNo; }

// ─── 사원 ───────────────────────────────────────────
var _empMap = null;
function empMap_() {
  if (_empMap) return _empMap;
  _empMap = {};
  rows_('employees').forEach(function (e) { var k = normEmp_(e.empNo); if (k) _empMap[k] = e; });
  return _empMap;
}
function employee_(empNo) {
  var k = normEmp_(empNo);
  if (!k) throw new AppError('사번을 입력해 주세요.');
  var e = empMap_()[k];
  if (!e) throw new AppError('사원명부에 없는 사번입니다. 사번을 확인하시거나 담당자에게 문의해 주세요.');
  return { empNo: k, name: String(e.name).trim(), team: String(e.team).trim(), email: String(e.email).trim().toLowerCase() };
}
function emailOf_(l) { var e = l.empNo && empMap_()[normEmp_(l.empNo)]; return (e && e.email) || l.email || ''; }

// ─── 상태 계산 ──────────────────────────────────────
function loanView_(l) {
  var t = today_();
  var v = {}; Object.keys(l).forEach(function (k) { if (k !== '_r') v[k] = l[k]; });
  v.dday = l.dueDate ? diffDays_(l.dueDate, t) : null;
  v.overdue = l.status === 'active' && v.dday !== null && v.dday < 0;
  v.overdueDays = v.overdue ? -v.dday : 0;
  v.waitingPickup = l.status === 'active' && !!l.pickupDate && t < l.pickupDate;
  // 소속·이름은 사원명부(현재 기준)를 우선 표시. 대출 당시 소속은 teamAtLoan으로 보존
  var e = l.empNo && empMap_()[normEmp_(l.empNo)];
  if (e) {
    var tn = String(e.team || '').trim(), nn = String(e.name || '').trim();
    if (nn) v.name = nn;
    if (tn && tn !== String(l.team || '').trim()) { v.teamAtLoan = l.team; v.team = tn; }
  }
  v.statusLabel = { active: v.overdue ? '연체 ' + v.overdueDays + '일' : v.waitingPickup ? '수령대기' : '대출중', returning: '반납확인중', returned: '반납완료', cancelled: '취소', lost: '분실' }[l.status] || l.status;
  return v;
}
function openByCode_() { var m = {}; rows_('loans').forEach(function (l) { if (OPEN.indexOf(l.status) >= 0) m[l.bookCode] = l; }); return m; }
function bookState_(b, open) {
  if (b.status === 'lost') return '분실';
  if (b.status === 'discarded') return '폐기';
  var l = open[b.code];
  if (!l) return '대출가능';
  return l.status === 'returning' ? '반납확인중' : '대출중';
}

// ─── 카탈로그 (전체를 한 번에 내려주고 검색은 브라우저에서) ──
function catalog_() {
  var cache = CacheService.getScriptCache();
  var hit = cacheGet_(cache, 'catalog_v2');
  if (hit) return hit;
  var open = openByCode_();
  var waiting = {};
  rows_('reservations').forEach(function (r) { if (r.status === 'waiting') waiting[r.key] = (waiting[r.key] || 0) + 1; });
  var newSince = addDays_(today_(), -settings_().newBookDays);
  var map = {}, order = [];
  rows_('books').forEach(function (b) {
    if (b.status === 'discarded' || !b.code) return;
    var k = titleKey_(b);
    if (!map[k]) {
      map[k] = { key: k, title: b.title, author: b.author, publisher: b.publisher, isbn: b.isbn, cover: b.cover || '', catCode: b.catCode,
        catName: catName_(b.catCode), group: groupOf_(b.catCode), copies: 0, available: 0, loanCount: 0, createdAt: b.createdAt || '', earliestDue: '', codes: [] };
      order.push(k);
    }
    var t = map[k];
    t.codes.push(b.code);
    if (!t.isbn && b.isbn) t.isbn = b.isbn;
    if (b.status === 'lost') return;
    t.copies++;
    t.loanCount += Number(b.loanCount) || 0;
    if (!t.cover && b.cover) t.cover = b.cover;
    if ((b.createdAt || '') > t.createdAt) t.createdAt = b.createdAt;
    var st = bookState_(b, open);
    if (st === '대출가능') t.available++;
    else { var l = open[b.code]; if (l && (!t.earliestDue || l.dueDate < t.earliestDue)) t.earliestDue = l.dueDate; }
  });
  var list = order.map(function (k) { var t = map[k]; t.isNew = !!t.createdAt && t.createdAt.slice(0, 10) >= newSince; t.waiting = waiting[k] || 0; return t; })
    .filter(function (t) { return t.copies > 0; });
  var out = { items: list, groups: categories_().map(function (c) { return { code: c.code, name: c.name, group: c.group, isGroup: c.isGroup }; }) };
  cachePut_(cache, 'catalog_v2', out, 600);
  return out;
}

// 100KB 제한을 넘는 값을 여러 조각으로 캐시
function cachePut_(cache, key, obj, ttl) {
  try {
    var s = JSON.stringify(obj), size = 90000, n = Math.ceil(s.length / size), m = {};
    for (var i = 0; i < n; i++) m[key + '_' + i] = s.slice(i * size, (i + 1) * size);
    m[key] = String(n);
    cache.putAll(m, ttl);
  } catch (e) {}
}
function cacheGet_(cache, key) {
  try {
    var n = Number(cache.get(key)); if (!n) return null;
    var keys = []; for (var i = 0; i < n; i++) keys.push(key + '_' + i);
    var parts = cache.getAll(keys); var s = '';
    for (var j = 0; j < n; j++) { if (parts[keys[j]] == null) return null; s += parts[keys[j]]; }
    return JSON.parse(s);
  } catch (e) { return null; }
}

function titleDetail_(key) {
  var books = rows_('books').filter(function (b) { return titleKey_(b) === key && b.status !== 'discarded'; });
  if (!books.length) throw new AppError('도서를 찾을 수 없습니다.');
  try { enrichOnce_(books); } catch (e) {}
  var open = openByCode_();
  var first = books[0];
  var pick = function (f) { var b = books.filter(function (x) { return x[f]; })[0]; return b ? b[f] : ''; };
  var copies = books.map(function (b) { var l = open[b.code]; return { code: b.code, status: bookState_(b, open), dueDate: l ? l.dueDate : '' }; });
  return {
    key: key, title: first.title, author: first.author, publisher: first.publisher, isbn: pick('isbn'), cover: pick('cover'), description: pick('description'),
    pubDate: pick('pubDate'), catCode: first.catCode, catName: catName_(first.catCode), groupName: groupName_(first.catCode), group: groupOf_(first.catCode),
    copies: copies, available: copies.filter(function (c) { return c.status === '대출가능'; }).length,
    waiting: rows_('reservations').filter(function (r) { return r.key === key && r.status === 'waiting'; }).length,
    loanCount: books.reduce(function (s, b) { return s + (Number(b.loanCount) || 0); }, 0), links: links_(pick('isbn'), first.title),
  };
}

// ─── 사번 확인 (신청 전 본인 확인용) ─────────────────
function whoAmI_(empNo) {
  var e = employee_(empNo);
  return { empNo: e.empNo, name: e.name, team: e.team, emailMasked: maskEmail_(e.email), hasEmail: !!e.email };
}

// ─── 대출 신청 ──────────────────────────────────────
function nextLoanNo_() { return rows_('loans').reduce(function (m, l) { return Math.max(m, Number(l.no) || 0); }, 0) + 1; }

function createLoan_(book, who, appliedDate, by) {
  var s = settings_();
  var pickup = nextBizDay_(appliedDate, s.holidays);
  var loan = {
    id: uid_(), no: nextLoanNo_(), bookCode: book.code, titleKey: titleKey_(book), bookTitle: book.title,
    empNo: who.empNo, name: who.name, team: who.team, email: who.email, appliedAt: nowIso_(),
    loanDate: appliedDate, pickupDate: pickup, dueDate: toBizDay_(addDays_(pickup, s.loanDays), s.holidays),
    status: 'active', extensions: [], extensionRequest: null, memo: '', createdBy: by,
  };
  book.loanCount = (Number(book.loanCount) || 0) + 1;
  save_('loans', loan);
  save_('books', book);
  return loan;
}

function applyLoan_(key, empNo) {
  var who = employee_(empNo);
  var s = settings_();
  var mine = rows_('loans').filter(function (l) { return normEmp_(l.empNo) === who.empNo && OPEN.indexOf(l.status) >= 0; }).map(loanView_);
  if (s.blockWhenOverdue && mine.some(function (l) { return l.overdue; })) throw new AppError('연체 중인 도서가 있어 신규 대출이 제한됩니다. 먼저 반납해 주세요.');
  if (mine.length >= s.maxLoansPerUser) throw new AppError('1인당 최대 ' + s.maxLoansPerUser + '권까지 대출할 수 있습니다.');
  if (mine.some(function (l) { return l.titleKey === key; })) throw new AppError('이미 대출 중인 도서입니다.');
  var open = openByCode_();
  var book = rows_('books').filter(function (b) { return titleKey_(b) === key; })
    .sort(function (a, b) { return Number(a.copyNo) - Number(b.copyNo); })
    .filter(function (b) { return bookState_(b, open) === '대출가능'; })[0];
  if (!book) throw new AppError('지금은 대출 가능한 권이 없습니다. 예약을 이용해 주세요.');
  var queue = rows_('reservations').filter(function (r) { return r.key === key && r.status === 'waiting'; }).sort(function (a, b) { return a.createdAt < b.createdAt ? -1 : 1; });
  if (queue.length && normEmp_(queue[0].empNo) !== who.empNo) throw new AppError('예약 대기자가 있는 도서입니다. 예약을 이용해 주세요.');
  if (queue.length) { queue[0].status = 'fulfilled'; save_('reservations', queue[0]); }
  var loan = createLoan_(book, who, today_(), 'user');
  notify_('applied', [loan]);
  return loanView_(loan);
}

// ─── 내 대출 (사번 조회) ─────────────────────────────
function myPage_(empNo) {
  var who = employee_(empNo);
  var loans = rows_('loans').filter(function (l) { return normEmp_(l.empNo) === who.empNo; }).map(loanView_)
    .sort(function (a, b) { return (b.appliedAt || b.loanDate) > (a.appliedAt || a.loanDate) ? 1 : -1; });
  var active = loans.filter(function (l) { return OPEN.indexOf(l.status) >= 0; });
  var cat = catalog_().items;
  var myRes = rows_('reservations').filter(function (r) { return normEmp_(r.empNo) === who.empNo && r.status === 'waiting'; }).map(function (r) {
    var q = rows_('reservations').filter(function (x) { return x.key === r.key && x.status === 'waiting'; }).sort(function (a, b) { return a.createdAt < b.createdAt ? -1 : 1; });
    var t = cat.filter(function (x) { return x.key === r.key; })[0];
    return { id: r.id, key: r.key, title: r.title, createdAt: r.createdAt, rank: q.map(function (x) { return x.id; }).indexOf(r.id) + 1, availableNow: !!(t && t.available > 0 && q[0].id === r.id), cover: t ? t.cover : '', isbn: t ? t.isbn : '', catCode: t ? t.catCode : '' };
  });
  var bookMap = {}; cat.forEach(function (t) { bookMap[t.key] = t; });
  loans.forEach(function (l) { var t = bookMap[l.titleKey]; l.cover = t ? t.cover : ''; l.isbn = t ? t.isbn : ''; l.email = ''; });
  var alerts = [];
  active.forEach(function (l) {
    if (l.overdue) alerts.push({ level: 'danger', text: '「' + l.bookTitle + '」 반납예정일(' + pretty_(l.dueDate) + ')이 ' + l.overdueDays + '일 지났습니다. 빠른 반납 부탁드립니다.' });
    else if (l.status === 'active' && l.dday <= 3) alerts.push({ level: 'warn', text: '「' + l.bookTitle + '」 반납예정일이 ' + (l.dday === 0 ? '오늘' : l.dday + '일 후') + '(' + pretty_(l.dueDate) + ')입니다.' });
    if (l.waitingPickup) alerts.push({ level: 'info', text: '「' + l.bookTitle + '」 ' + pretty_(l.pickupDate) + ' 14:00 이후 대출도서 칸에서 수령하세요.' });
    if (l.extensionRequest && l.extensionRequest.status === 'pending') alerts.push({ level: 'info', text: '「' + l.bookTitle + '」 연장 신청이 담당자 승인 대기 중입니다.' });
  });
  myRes.forEach(function (r) { if (r.availableNow) alerts.push({ level: 'success', text: '예약하신 「' + r.title + '」을(를) 지금 대출 신청할 수 있습니다.', key: r.key }); });
  return { me: { empNo: who.empNo, name: who.name, team: who.team, emailMasked: maskEmail_(who.email) }, active: active, history: loans.filter(function (l) { return OPEN.indexOf(l.status) < 0; }).slice(0, 30), reservations: myRes, alerts: alerts };
}

function ownLoan_(loanId, empNo) {
  var who = employee_(empNo);
  var l = rows_('loans').filter(function (x) { return x.id === loanId; })[0];
  if (!l || normEmp_(l.empNo) !== who.empNo) throw new AppError('대출 정보를 찾을 수 없습니다.');
  return l;
}

function requestReturn_(loanId, empNo) {
  var l = ownLoan_(loanId, empNo);
  if (l.status !== 'active') throw new AppError('반납 등록할 수 없는 상태입니다.');
  l.status = 'returning';
  l.returnRequestedAt = nowIso_();
  save_('loans', l);
  if (settings_().autoConfirmReturn) confirmReturn_([l.id], '자동확인');
  return loanView_(l);
}

function canExtend_(l) {
  var s = settings_(), v = loanView_(l);
  if (l.status !== 'active') return '대출 중인 도서만 연장할 수 있습니다.';
  if (v.overdue) return '연체된 도서는 연장할 수 없습니다. 반납 후 다시 신청해 주세요.';
  if ((l.extensions || []).length >= s.maxExtensions) return '연장은 ' + s.maxExtensions + '회까지 가능합니다. 더 필요하시면 반납 후 다시 신청해 주세요.';
  if (rows_('reservations').some(function (r) { return r.key === l.titleKey && r.status === 'waiting'; })) return '예약 대기자가 있어 연장할 수 없습니다.';
  return null;
}
function doExtend_(l, by) {
  var s = settings_();
  var nd = toBizDay_(addDays_(l.dueDate, s.extendDays), s.holidays);
  l.extensions = (l.extensions || []).concat([{ at: nowIso_(), from: l.dueDate, to: nd, by: by }]);
  l.dueDate = nd;
  if (l.extensionRequest) l.extensionRequest = { at: l.extensionRequest.at, status: 'approved' };
}
function requestExtend_(loanId, empNo) {
  var l = ownLoan_(loanId, empNo);
  var why = canExtend_(l);
  if (why) throw new AppError(why);
  if (l.extensionRequest && l.extensionRequest.status === 'pending') throw new AppError('이미 연장 신청 중입니다.');
  l.extensionRequest = { at: nowIso_(), status: 'pending' };
  if (settings_().autoApproveExtension) {
    doExtend_(l, 'auto');
    save_('loans', l);
    notify_('extended', [l]);
    var v = loanView_(l); v.autoApproved = true; return v;
  }
  save_('loans', l);
  return loanView_(l);
}

function reserve_(key, empNo) {
  var who = employee_(empNo);
  var t = catalog_().items.filter(function (x) { return x.key === key; })[0];
  if (!t) throw new AppError('도서를 찾을 수 없습니다.');
  if (t.available > 0 && !t.waiting) throw new AppError('지금 바로 대출 신청할 수 있는 도서입니다.');
  if (rows_('loans').some(function (l) { return normEmp_(l.empNo) === who.empNo && l.titleKey === key && OPEN.indexOf(l.status) >= 0; })) throw new AppError('이미 대출 중인 도서입니다.');
  if (rows_('reservations').some(function (r) { return normEmp_(r.empNo) === who.empNo && r.key === key && r.status === 'waiting'; })) throw new AppError('이미 예약한 도서입니다.');
  var r = { id: uid_(), key: key, title: t.title, empNo: who.empNo, name: who.name, team: who.team, email: who.email, createdAt: nowIso_(), status: 'waiting', notifiedAt: '' };
  save_('reservations', r);
  return { id: r.id, title: r.title, rank: rows_('reservations').filter(function (x) { return x.key === key && x.status === 'waiting'; }).length };
}

function cancelReservation_(id, empNo, admin) {
  var r = rows_('reservations').filter(function (x) { return x.id === id; })[0];
  if (!r || (!admin && normEmp_(r.empNo) !== employee_(empNo).empNo)) throw new AppError('예약 정보를 찾을 수 없습니다.');
  r.status = 'cancelled';
  save_('reservations', r);
  return { ok: true };
}

// ─── 관리자 ─────────────────────────────────────────
function confirmReturn_(ids, adminName) {
  var done = [];
  rows_('loans').forEach(function (l) {
    if (ids.indexOf(l.id) >= 0 && OPEN.indexOf(l.status) >= 0) { l.status = 'returned'; l.returnedAt = today_(); l.returnedBy = adminName || '관리자'; done.push(l); }
  });
  save_('loans', done);
  var keys = {}; done.forEach(function (l) { keys[l.titleKey] = 1; });
  Object.keys(keys).forEach(function (k) {
    var q = rows_('reservations').filter(function (r) { return r.key === k && r.status === 'waiting'; }).sort(function (a, b) { return a.createdAt < b.createdAt ? -1 : 1; });
    if (q.length && !q[0].notifiedAt) { q[0].notifiedAt = nowIso_(); save_('reservations', q[0]); notify_('reservationReady', [], { reservation: q[0] }); }
  });
  return { count: done.length };
}

function findLoan_(id) { var l = rows_('loans').filter(function (x) { return x.id === id; })[0]; if (!l) throw new AppError('대출 정보를 찾을 수 없습니다.'); return l; }

function adminExtend_(id, approve) {
  var l = findLoan_(id);
  if (!approve) {
    if (l.extensionRequest) l.extensionRequest = { at: l.extensionRequest.at, status: 'rejected' };
    save_('loans', l); notify_('extensionRejected', [l]); return loanView_(l);
  }
  if (l.status !== 'active') throw new AppError('대출 중인 도서만 연장할 수 있습니다.');
  doExtend_(l, 'admin'); save_('loans', l); notify_('extended', [l]);
  return loanView_(l);
}

function setLoanStatus_(id, status) {
  var l = findLoan_(id);
  l.status = status; save_('loans', l);
  if (status === 'lost') { var b = rows_('books').filter(function (x) { return x.code === l.bookCode; })[0]; if (b) { b.status = 'lost'; save_('books', b); } }
  return loanView_(l);
}

function updateLoan_(id, patch) {
  var l = findLoan_(id);
  if (patch.empNo !== undefined) {
    var e = employee_(patch.empNo);
    l.empNo = e.empNo; l.name = e.name; l.team = e.team; l.email = e.email;
  }
  ['dueDate', 'memo'].forEach(function (k) { if (patch[k] !== undefined) l[k] = patch[k]; });
  save_('loans', l);
  return loanView_(l);
}

function adminCreateLoan_(code, empNo, appliedDate) {
  var who = employee_(empNo);
  var b = rows_('books').filter(function (x) { return x.code === code; })[0];
  if (!b) throw new AppError('도서코드를 찾을 수 없습니다.');
  if (openByCode_()[code]) throw new AppError('이미 대출 중인 권입니다.');
  var l = createLoan_(b, who, appliedDate || today_(), 'admin');
  notify_('applied', [l]);
  return loanView_(l);
}

function adminLoans_(status, q) {
  var list = rows_('loans').map(loanView_);
  if (status === 'open') list = list.filter(function (l) { return OPEN.indexOf(l.status) >= 0; });
  else if (status === 'overdue') list = list.filter(function (l) { return l.overdue; });
  else if (status === 'noemp') list = list.filter(function (l) { return OPEN.indexOf(l.status) >= 0 && !emailOf_(l); });
  else if (status !== 'all') list = list.filter(function (l) { return l.status === status; });
  if (q) { q = String(q).toLowerCase(); list = list.filter(function (l) { return [l.bookCode, l.bookTitle, l.name, l.team, l.empNo].join(' ').toLowerCase().indexOf(q) >= 0; }); }
  list.forEach(function (l) { l.mail = emailOf_(l); });
  return list.sort(function (a, b) { return (Number(b.no) || 0) - (Number(a.no) || 0); }).slice(0, 400);
}

function dashboard_() {
  var loans = rows_('loans').map(loanView_);
  var open = loans.filter(function (l) { return OPEN.indexOf(l.status) >= 0; });
  open.forEach(function (l) { l.mail = emailOf_(l); });
  var t = today_();
  var books = rows_('books').filter(function (b) { return b.status !== 'discarded'; });
  var titles = {}; books.forEach(function (b) { titles[titleKey_(b)] = 1; });
  var months = [];
  for (var i = 11; i >= 0; i--) { var d = new Date(Date.UTC(Number(t.slice(0, 4)), Number(t.slice(5, 7)) - 1 - i, 1)); months.push(d.toISOString().slice(0, 7)); }
  var monthly = months.map(function (m) { return { month: m, count: loans.filter(function (l) { return String(l.loanDate).slice(0, 7) === m && l.status !== 'cancelled'; }).length }; });
  var popular = catalog_().items.slice().sort(function (a, b) { return b.loanCount - a.loanCount; }).slice(0, 8).map(function (x) { return { title: x.title, count: x.loanCount }; });
  var dueSoon = open.filter(function (l) { return l.status === 'active' && !l.overdue && l.dday <= 3; });
  return {
    today: t,
    counts: {
      books: books.length, titles: Object.keys(titles).length, open: open.filter(function (l) { return l.status === 'active'; }).length,
      overdue: open.filter(function (l) { return l.overdue; }).length, dueSoon: dueSoon.length,
      returning: open.filter(function (l) { return l.status === 'returning'; }).length,
      extensionPending: open.filter(function (l) { return l.extensionRequest && l.extensionRequest.status === 'pending'; }).length,
      noEmail: open.filter(function (l) { return !l.mail; }).length,
      thisMonth: loans.filter(function (l) { return String(l.loanDate).slice(0, 7) === t.slice(0, 7) && l.status !== 'cancelled'; }).length,
      employees: rows_('employees').length,
      noCover: books.filter(function (b) { return !b.cover; }).length,
    },
    overdue: open.filter(function (l) { return l.overdue; }).sort(function (a, b) { return a.dday - b.dday; }),
    dueSoon: dueSoon.sort(function (a, b) { return a.dday - b.dday; }),
    returning: open.filter(function (l) { return l.status === 'returning'; }),
    extensionRequests: open.filter(function (l) { return l.extensionRequest && l.extensionRequest.status === 'pending'; }),
    reservations: rows_('reservations').filter(function (r) { return r.status === 'waiting'; }).map(function (r) { return { id: r.id, title: r.title, name: r.name, team: r.team, createdAt: r.createdAt }; }),
    monthly: monthly, popular: popular,
    mail: { enabled: settings_().mail.enabled, sendHour: settings_().mail.sendHour, lastRun: meta_('lastMailRun') || '', quota: mailQuota_(), triggerOk: triggerInstalled_() },
  };
}

function addBooks_(input) {
  if (!input.title || !String(input.title).trim()) throw new AppError('도서명을 입력해 주세요.');
  var cat = leafCategories_().filter(function (c) { return c.code === String(input.catCode); })[0];
  if (!cat) throw new AppError('분류를 선택해 주세요.');
  var n = Math.max(1, Math.min(20, Number(input.count) || 1));
  var codes = nextCode_(cat.code, input, n).codes;
  var now = nowIso_();
  var isbn = String(input.isbn || '').replace(/\D/g, '');
  var created = codes.map(function (c) {
    return { code: c.code, catCode: c.catCode, purchaseNo: c.purchaseNo, copyNo: c.copyNo, title: String(input.title).trim(), author: input.author || '', publisher: input.publisher || '',
      isbn: isbn, cover: input.cover || '', description: String(input.description || '').slice(0, 3000), pubDate: input.pubDate || '', kdc: input.kdc || '',
      status: 'active', loanCount: 0, createdAt: now, coverCheckedAt: input.cover ? today_() : '' };
  });
  save_('books', created);
  var fulfilled = 0;
  try { fulfilled = fulfillRequests_(created); } catch (e) { console.error('fulfillRequests', e); }
  return created.map(function (b) { return { code: b.code, title: b.title, fulfilled: fulfilled }; });
}

function updateBook_(code, patch) {
  var b = rows_('books').filter(function (x) { return x.code === code; })[0];
  if (!b) throw new AppError('도서를 찾을 수 없습니다.');
  ['title', 'author', 'publisher', 'isbn', 'cover', 'status'].forEach(function (k) { if (patch[k] !== undefined) b[k] = k === 'isbn' ? String(patch[k]).replace(/\D/g, '') : patch[k]; });
  if (patch.isbn !== undefined && !patch.cover) { b.cover = ''; b.coverCheckedAt = ''; }
  save_('books', b);
  return { ok: true };
}

function adminBooks_(q) {
  var open = openByCode_();
  var list = rows_('books');
  if (q) { q = String(q).toLowerCase(); list = list.filter(function (b) { return [b.code, b.title, b.author, b.publisher, b.isbn].join(' ').toLowerCase().indexOf(q) >= 0; }); }
  return list.slice().sort(function (a, b) { return (b.createdAt || '') > (a.createdAt || '') ? 1 : (b.createdAt || '') < (a.createdAt || '') ? -1 : a.code.localeCompare(b.code, undefined, { numeric: true }); })
    .slice(0, 300).map(function (b) { return { code: b.code, title: b.title, author: b.author, publisher: b.publisher, isbn: b.isbn, cover: b.cover, status: b.status, loanCount: b.loanCount, catName: catName_(b.catCode), groupName: groupName_(b.catCode), state: bookState_(b, open) }; });
}

function addCategory_(code, name, keywords) {
  code = String(code || '').trim();
  if (!/^\d{3,4}$/.test(code)) throw new AppError('분류번호는 3~4자리 숫자입니다.');
  if (categories_().some(function (c) { return c.code === code; })) throw new AppError('이미 있는 분류번호입니다.');
  save_('categories', { code: code, name: String(name).trim(), keywords: String(keywords || '').split(',').map(function (s) { return s.trim().toLowerCase(); }).filter(String) });
  _cats = null;
  return { ok: true };
}
function updateCategory_(code, keywords) {
  var c = rows_('categories').filter(function (x) { return x.code === code; })[0];
  if (!c) throw new AppError('분류를 찾을 수 없습니다.');
  c.keywords = String(keywords || '').split(',').map(function (s) { return s.trim().toLowerCase(); }).filter(String);
  save_('categories', c);
  return { ok: true };
}
function nextCategoryCode_(group) {
  var sibs = categories_().filter(function (c) { return c.group === String(group) && !c.isGroup; }).map(function (c) { return Number(c.code); });
  return String((sibs.length ? Math.max.apply(null, sibs) : Number(group)) + 1);
}

// ─── 데이터 점검 ─────────────────────────────────────
// 원본 시트에서 반납 처리가 누락된 기록: 같은 권(도서코드)을 이후에 다른 사람이 빌린 기록이 있는데 아직 '대출중'으로 남은 경우
function laterLoans_(l, loans) {
  return loans.filter(function (x) {
    return x !== l && x.bookCode === l.bookCode && x.status !== 'cancelled' &&
      (String(x.loanDate) > String(l.loanDate) || (String(x.loanDate) === String(l.loanDate) && Number(x.no) > Number(l.no)));
  }).sort(function (a, b) { return String(a.loanDate).localeCompare(String(b.loanDate)); });
}
function dataCheck_() {
  var loans = rows_('loans');
  var open = loans.filter(function (l) { return OPEN.indexOf(l.status) >= 0; });
  var stale = [];
  open.forEach(function (l) {
    var later = laterLoans_(l, loans);
    if (later.length) { var v = loanView_(l); v.later = later.slice(0, 3).map(function (x) { return { no: x.no, name: x.name, loanDate: x.loanDate, status: loanView_(x).statusLabel }; }); stale.push(v); }
  });
  var byCode = {};
  open.forEach(function (l) { (byCode[l.bookCode] = byCode[l.bookCode] || []).push(l); });
  var dup = Object.keys(byCode).filter(function (k) { return byCode[k].length > 1; }).map(function (k) { return { bookCode: k, loans: byCode[k].map(loanView_) }; });
  var noEmp = open.filter(function (l) { return !l.empNo; }).map(loanView_);
  return { stale: stale, dup: dup, noEmp: noEmp, openCount: open.length };
}
function fixStale_(ids, admin) {
  var loans = rows_('loans'), done = [];
  [].concat(ids).forEach(function (id) {
    var l = loans.filter(function (x) { return x.id === id; })[0];
    if (!l || OPEN.indexOf(l.status) < 0) return;
    var later = laterLoans_(l, loans);
    if (!later.length) return;
    l.status = 'returned';
    l.returnedAt = later[0].loanDate || today_();
    l.returnedBy = admin || '자동정리';
    l.memo = [l.memo, '[' + today_() + ' 데이터 점검: 이후 ' + later[0].name + '님 대출(' + later[0].loanDate + ') 기록이 있어 반납 처리]'].filter(String).join(' ');
    done.push(l);
  });
  save_('loans', done);
  return { fixed: done.length };
}

// ─── 내보내기 (CSV) ──────────────────────────────────
function csv_(rows) {
  return rows.map(function (r) { return r.map(function (c) { c = c == null ? '' : String(c); return /[",\n\r]/.test(c) ? '"' + c.replace(/"/g, '""') + '"' : c; }).join(','); }).join('\r\n');
}
function exportData_(kind) {
  var t = today_();
  if (kind === 'books') {
    var open = openByCode_();
    var rows = [['도서코드', '분류번호', '분류명', '구매번호', '도서번호', '도서명', '저자', '출판사', 'ISBN', '상태', '현재 대출자', '반납예정일', '누적 대출횟수', '등록일']];
    rows_('books').forEach(function (b) {
      var st = bookState_(b, open), l = open[b.code], v = l ? loanView_(l) : null;
      rows.push([b.code, b.catCode, catName_(b.catCode), b.purchaseNo, b.copyNo, b.title, b.author, b.publisher, b.isbn, v && v.overdue ? '연체' : st, v ? v.name + ' (' + v.team + ')' : '', v ? v.dueDate : '', b.loanCount, String(b.createdAt || '').slice(0, 10)]);
    });
    return { name: '오스템문고_도서목록_' + t + '.csv', csv: csv_(rows), count: rows.length - 1 };
  }
  if (kind === 'loans') {
    var rows2 = [['번호', '도서코드', '도서명', '사번', '성명', '현재 소속', '대출 당시 소속', '대출일', '수령일', '반납예정일', '상태', '연체일수', '반납확인일', '반납확인자', '연장횟수', '메모']];
    rows_('loans').map(loanView_).sort(function (a, b) { return (Number(a.no) || 0) - (Number(b.no) || 0); }).forEach(function (v) {
      rows2.push([v.no, v.bookCode, v.bookTitle, v.empNo, v.name, v.team, v.teamAtLoan || v.team, v.loanDate, v.pickupDate, v.dueDate, v.statusLabel, v.overdueDays || '', v.returnedAt, v.returnedBy, (v.extensions || []).length || '', v.memo]);
    });
    return { name: '오스템문고_대출기록_' + t + '.csv', csv: csv_(rows2), count: rows2.length - 1 };
  }
  throw new AppError('알 수 없는 내보내기 종류입니다.');
}

// ===== Mail.gs =====
// 메일: 즉시 안내(신청·연장·예약) + 매일 자동 리마인더(반납예정·연체) + 주간 관리자 요약
function mailQuota_() { try { return MailApp.getRemainingDailyQuota(); } catch (e) { return null; } }

function layout_(title, body, accent) {
  var s = settings_(); accent = accent || '#d9480f';
  var url = props_().getProperty('WEBAPP_URL') || '';
  return '<div style="font-family:\'Noto Sans KR\',\'Malgun Gothic\',\'Apple SD Gothic Neo\',sans-serif;max-width:600px;margin:0 auto;color:#17242c">' +
    '<div style="border:1px solid #e3e8e6;border-top:4px solid ' + accent + ';padding:22px 24px;background:#fff">' +
    '<div style="font-size:13px;color:#7b8a92">' + esc_(s.libraryName) + '</div><h2 style="margin:6px 0 16px;font-size:20px">' + title + '</h2>' + body +
    '<p style="margin-top:24px;font-size:12px;color:#7b8a92;line-height:1.7">📍 ' + esc_(s.location) + '<br>문의: ' + esc_(s.managerName) + (s.managerPhone ? ' · ' + esc_(s.managerPhone) : '') +
    (url ? '<br><a href="' + url + '" style="color:' + accent + ';font-weight:bold">오스템문고 바로가기 (사번으로 내 대출 확인)</a>' : '') + '</p></div></div>';
}
function table_html_(rows, cols) {
  var th = cols.map(function (c) { return '<th style="text-align:left;padding:8px;border-bottom:1px solid #e3e8e6;font-size:12px;color:#7b8a92">' + c[0] + '</th>'; }).join('');
  var tr = rows.map(function (r) { return '<tr>' + cols.map(function (c) { return '<td style="padding:8px;border-bottom:1px solid #f1f3f2;font-size:14px">' + c[1](r) + '</td>'; }).join('') + '</tr>'; }).join('');
  return '<table style="width:100%;border-collapse:collapse"><tr>' + th + '</tr>' + tr + '</table>';
}
function bookCell_(l) { return '<b>' + esc_(l.bookTitle) + '</b> <span style="color:#7b8a92">(' + esc_(l.bookCode) + ')</span>'; }

function sendMail_(o) {
  var s = settings_();
  var to = [].concat(o.to || []).filter(Boolean), cc = [].concat(o.cc || []).filter(Boolean);
  var entry = { at: nowIso_(), type: o.type, to: to, cc: cc, subject: o.subject, status: 'sent', error: '', keys: o.keys || [], html: o.html };
  if (!to.length) { entry.status = '수신자없음'; entry.error = '사원명부에 이메일이 없습니다'; }
  else if (!s.mail.enabled) { entry.status = '발송꺼짐'; }
  else {
    try {
      MailApp.sendEmail({ to: to.join(','), cc: cc.join(','), subject: o.subject, htmlBody: o.html, name: s.libraryName, replyTo: s.managerEmail || undefined });
      entry.status = '발송';
    } catch (e) { entry.status = '실패'; entry.error = String(e.message || e); }
  }
  appendLog_(entry);
  return entry;
}

function notify_(kind, loans, extra) {
  var s = settings_(); var l = loans[0];
  try {
    if (kind === 'applied') {
      sendMail_({ type: '신청확인', to: emailOf_(l), subject: '[' + s.libraryName + '] 대출 신청 완료 – ' + l.bookTitle,
        html: layout_('대출 신청이 접수되었습니다', '<p>' + esc_(l.name) + '님, 아래 도서의 대출 신청이 완료되었습니다.</p>' +
          table_html_([l], [['도서', bookCell_], ['수령', function (x) { return pretty_(x.pickupDate) + ' 14:00~18:00'; }], ['반납예정일', function (x) { return '<b>' + pretty_(x.dueDate) + '</b>'; }]]) +
          '<p style="font-size:14px;line-height:1.8">· ' + esc_(s.location) + ' <b>대출도서 칸</b>에서 직접 수령해 주세요.<br>· 반납할 때는 <b>반납도서 칸</b>에 넣고, 사이트 \'내 대출\'에서 [반납했어요]를 눌러주세요.<br>· 분실 시 실물로 변상합니다.</p>') });
    } else if (kind === 'extended') {
      sendMail_({ type: '연장완료', to: emailOf_(l), subject: '[' + s.libraryName + '] 대출 연장 완료 – ' + l.bookTitle,
        html: layout_('대출 기간이 연장되었습니다', '<p>' + esc_(l.name) + '님, 연장이 완료되었습니다.</p>' + table_html_([l], [['도서', bookCell_], ['새 반납예정일', function (x) { return '<b>' + pretty_(x.dueDate) + '</b>'; }]])) });
    } else if (kind === 'extensionRejected') {
      sendMail_({ type: '연장거절', to: emailOf_(l), subject: '[' + s.libraryName + '] 대출 연장 불가 안내 – ' + l.bookTitle,
        html: layout_('대출 연장이 어렵습니다', '<p>' + esc_(l.name) + '님, 아래 도서는 연장이 어려워 기존 반납예정일까지 반납 부탁드립니다.</p>' + table_html_([l], [['도서', bookCell_], ['반납예정일', function (x) { return '<b>' + pretty_(x.dueDate) + '</b>'; }]]), '#a8660f') });
    } else if (kind === 'reservationReady') {
      var r = extra.reservation;
      var e = empMap_()[normEmp_(r.empNo)];
      sendMail_({ type: '예약도서', to: (e && e.email) || r.email, subject: '[' + s.libraryName + '] 예약 도서 대출 가능 – ' + r.title,
        html: layout_('예약하신 도서를 대출할 수 있습니다', '<p>' + esc_(r.name) + '님, 예약하신 <b>「' + esc_(r.title) + '」</b>이(가) 반납되었습니다.</p><p>사이트에서 대출 신청해 주세요. 1순위 예약자에게 우선권이 있습니다.</p>') });
    }
  } catch (err) { console.error(err); }
}

// 오늘 보낼 리마인더 계산 (이미 보낸 안내는 다시 보내지 않음)
function planReminders_() {
  var s = settings_(), t = today_();
  var sent = {}, lastOver = {};
  columns_('mailLog', ['type', 'status', 'keys']).forEach(function (m) {
    if (m.type !== '반납안내' || (m.status !== '발송')) return;
    (m.keys || []).forEach(function (k) {
      sent[k] = 1;
      var p = k.split('|');
      if (p[1] === 'overdue' && (!lastOver[p[0]] || p[2] > lastOver[p[0]])) lastOver[p[0]] = p[2];
    });
  });
  var th = s.mail.dueSoonDays.map(Number).sort(function (a, b) { return a - b; });
  var byUser = {}, noEmail = [];
  rows_('loans').forEach(function (raw) {
    if (raw.status !== 'active') return;
    var l = loanView_(raw), item = null;
    if (l.overdue) {
      var last = lastOver[l.id];
      if (!last || diffDays_(t, last) >= s.mail.overdueRepeatDays) item = { kind: 'overdue', keys: [l.id + '|overdue|' + t] };
    } else {
      var d = th.filter(function (x) { return l.dday <= x && l.dday >= 0; })[0];
      if (d !== undefined && !sent[l.id + '|due' + d + '|' + l.dueDate]) item = { kind: 'dueSoon', keys: th.filter(function (x) { return x >= d; }).map(function (x) { return l.id + '|due' + x + '|' + l.dueDate; }) };
    }
    if (!item) return;
    var mail = emailOf_(raw);
    if (!mail) { noEmail.push(l); return; }
    var u = byUser[mail] = byUser[mail] || { email: mail, name: l.name, overdue: [], dueSoon: [], keys: [] };
    u[item.kind].push(l); u.keys = u.keys.concat(item.keys);
  });
  return { users: Object.keys(byUser).map(function (k) { return byUser[k]; }), noEmail: noEmail };
}

function runReminders_(force, dryRun) {
  var s = settings_(), t = today_();
  if (!force && !isBizDay_(t, s.holidays)) return { skipped: '휴무일' };
  var plan = planReminders_();
  if (dryRun) return {
    plan: plan.users.map(function (u) { return { name: u.name, email: maskEmail_(u.email), overdue: u.overdue.map(function (l) { return l.bookTitle; }), dueSoon: u.dueSoon.map(function (l) { return l.bookTitle + ' (' + (l.dday === 0 ? '오늘' : 'D-' + l.dday) + ')'; }) }; }),
    noEmail: plan.noEmail.map(function (l) { return l.name + ' · ' + l.bookTitle; }),
  };
  var sent = 0;
  plan.users.forEach(function (u) {
    var over = u.overdue.length > 0, parts = '';
    if (over) parts += '<p style="color:#b8322a"><b>반납예정일이 지난 도서</b>가 있습니다. 반납도서 칸에 반납 후 사이트에서 [반납했어요]를 눌러주세요.</p>' +
      table_html_(u.overdue, [['도서', bookCell_], ['반납예정일', function (x) { return pretty_(x.dueDate); }], ['연체', function (x) { return '<b style="color:#b8322a">' + x.overdueDays + '일</b>'; }]]);
    if (u.dueSoon.length) parts += '<p style="margin-top:16px"><b>반납예정일이 다가온 도서</b>입니다. 더 읽으셔야 하면 사이트에서 ' + s.extendDays + '일 연장을 신청할 수 있습니다.</p>' +
      table_html_(u.dueSoon, [['도서', bookCell_], ['반납예정일', function (x) { return '<b>' + pretty_(x.dueDate) + '</b>'; }], ['남은 기간', function (x) { return x.dday === 0 ? '<b>오늘</b>' : 'D-' + x.dday; }]]);
    var subject = over ? '[' + s.libraryName + '] 연체 도서 반납 요청 (' + u.overdue.length + '권)'
      : '[' + s.libraryName + '] 반납예정일 안내 – ' + u.dueSoon[0].bookTitle + (u.dueSoon.length > 1 ? ' 외 ' + (u.dueSoon.length - 1) + '권' : '');
    var e = sendMail_({ type: '반납안내', to: u.email, cc: over && s.mail.ccAdminOnOverdue && s.managerEmail ? [s.managerEmail] : [], subject: subject, keys: u.keys,
      html: layout_(over ? '연체 도서 반납 요청' : '반납예정일 안내', '<p>' + esc_(u.name) + '님, 안녕하세요.</p>' + parts, over ? '#b8322a' : '#0f5e52') });
    if (e.status === '발송') sent++;
  });
  // 주간 요약: 이번 주 첫 영업일
  var first = isBizDay_(t, s.holidays);
  var w = dow_(t);
  for (var i = 1; i < (w === 0 ? 7 : w) && first; i++) if (isBizDay_(addDays_(t, -i), s.holidays)) first = false;
  if (s.mail.adminDigest && s.managerEmail && (first || force) && meta_('lastDigest') !== t) {
    var d = dashboard_();
    sendMail_({ type: '관리자요약', to: s.managerEmail, subject: '[' + s.libraryName + '] 대출 현황 요약 (' + t + ')',
      html: layout_('관리자 대출 현황 요약', '<p>대출 중 <b>' + d.counts.open + '</b>건 · 연체 <b style="color:#b8322a">' + d.counts.overdue + '</b>건 · 반납확인 대기 <b>' + d.counts.returning + '</b>건 · 연장승인 대기 <b>' + d.counts.extensionPending + '</b>건 · 이메일 없음 <b>' + d.counts.noEmail + '</b>건</p>' +
        (d.overdue.length ? '<h3 style="font-size:15px">연체자</h3>' + table_html_(d.overdue, [['성명', function (x) { return esc_(x.name) + ' <span style="color:#7b8a92">' + esc_(x.team) + '</span>'; }], ['도서', bookCell_], ['연체', function (x) { return x.overdueDays + '일'; }]]) : '')) });
    meta_('lastDigest', t);
  }
  meta_('lastMailRun', nowIso_());
  return { sent: sent, noEmail: plan.noEmail.length };
}

function appendLog_(entry) {
  var def = TABLES.mailLog;
  var sh = db_().getSheetByName(def.sheet);
  var header = sh.getRange(1, 1, 1, sh.getLastColumn()).getValues()[0];
  var row = header.map(function (h) { var c = def.cols.filter(function (x) { return x[1] === h; })[0]; return c ? cellIn_(c[0], entry[c[0]]) : ''; });
  sh.getRange(sh.getLastRow() + 1, 1, 1, row.length).setValues([row]);
}

